def fib_like(n):
    if n < 2:
        return n
    return fib_like(n - 1) + fib_like(n - 2)

def total_evens(xs):
    total = 0
    for x in xs:
        if x % 2 == 0:
            total += x
    return total

def first_index(xs, target):
    i = 0
    while i < len(xs):
        if xs[i] == target:
            return i
        i += 1
    return -1

def count_chars(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

def shout_words(s):
    parts = s.split(" ")
    out = []
    for p in parts:
        if p:
            out.append(p.upper())
    return "-".join(out)

def apply_twice(n):
    def bump(v):
        return v * 2 + 1
    return bump(bump(n))

def pair_sums(xs):
    out = []
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            out.append(xs[i] + xs[j])
    return out

def until_negative(xs):
    out = []
    for x in xs:
        if x == 0:
            continue
        if x < 0:
            break
        out.append(x)
    return out

def classify(n):
    if n < 0:
        return "neg"
    elif n == 0:
        return "zero"
    else:
        return "pos"

def scale(v, factor):
    return v * factor


def normalize_all(xs):
    biggest = 0
    for x in xs:
        if x > biggest:
            biggest = x
    if biggest == 0:
        return []
    return [scale(x, 100) // biggest for x in xs]

def stats_of(xs):
    if not xs:
        return (0, 0.0)
    total = 0
    for x in xs:
        total += x
    return (total, total / len(xs))
